package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.material3.*;import androidx.compose.runtime.*;import com.example.aymobiledigitallibrary.data.LibraryItem;import com.example.aymobiledigitallibrary.model.*;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun RelativeOrderRecallScreen(pairs:List<Pair<LibraryItem,LibraryItem>>,onDone:(List<RecallAnswer>)->Unit){var i by remember{ mutableIntStateOf(0)};var start by remember{ mutableLongStateOf(System.currentTimeMillis())};val out=remember{ mutableStateListOf<RecallAnswer>()};val (a,b)=pairs[i];ScreenContainer{TaskProgressHeader("Material Review",i+1,pairs.size);QuestionCard{Text("Which material appeared first?");Text("A: ${a.title}");Text("B: ${b.title}");ChoiceButton("Material A",false){val c=if(a.id<b.id) a.id else b.id;out+=RecallAnswer(TaskType.RELATIVE_ORDER,"${a.id}|${b.id}",c,a.id,null,c==a.id,System.currentTimeMillis()-start);if(i==pairs.lastIndex) onDone(out) else {i++;start=System.currentTimeMillis()}};ChoiceButton("Material B",false){val c=if(a.id<b.id) a.id else b.id;out+=RecallAnswer(TaskType.RELATIVE_ORDER,"${a.id}|${b.id}",c,b.id,null,c==b.id,System.currentTimeMillis()-start);if(i==pairs.lastIndex) onDone(out) else {i++;start=System.currentTimeMillis()}}}}}
